package com.ruoyi.web.controller.library;
import com.ruoyi.common.annotation.Log;import com.ruoyi.common.core.controller.BaseController;import com.ruoyi.common.core.domain.AjaxResult;import com.ruoyi.common.core.page.TableDataInfo;import com.ruoyi.common.enums.BusinessType;import com.ruoyi.library.domain.*;import com.ruoyi.library.service.CourseService;import java.util.List;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
/** 后台课程和私有视频管理接口。 */@RestController @RequestMapping("/library/course") public class LibraryCourseController extends BaseController
{private final CourseService service;public LibraryCourseController(CourseService s){service=s;}/** 分页查询课程。 */@PreAuthorize("@ss.hasPermi('library:course:list')")@GetMapping("/list")public TableDataInfo list(WlCourse q){startPage();return getDataTable(service.list(q));}/** 新增课程。 */@PreAuthorize("@ss.hasPermi('library:course:add')")@Log(title="课程管理",businessType=BusinessType.INSERT)@PostMapping public AjaxResult add(@RequestBody WlCourse c){return toAjax(service.add(c,getUsername()));}/** 修改课程，已有使用记录时禁止改变访问类型。 */@PreAuthorize("@ss.hasPermi('library:course:edit')")@Log(title="课程管理",businessType=BusinessType.UPDATE)@PutMapping public AjaxResult edit(@RequestBody WlCourse c){return toAjax(service.edit(c,getUsername()));}/** 查询课程视频。 */@PreAuthorize("@ss.hasPermi('library:course:list')")@GetMapping("/{id}/videos")public AjaxResult videos(@PathVariable Long id){return success(service.videos(id));}/** 新增或修改课程视频。 */@PreAuthorize("@ss.hasPermi('library:course:edit')")@PutMapping("/video")public AjaxResult video(@RequestBody WlCourseVideo v){return toAjax(service.saveVideo(v,getUsername()));}}
